# Instalador de entrega para NeuroDAC.
# Generado automaticamente: no se edita, se vuelve a generar.
#
# Uso, desde la raiz del repositorio:
#     Unblock-File .\entrega_protocolo.ps1
#     .\entrega_protocolo.ps1              # instala
#     .\entrega_protocolo.ps1 -Simular     # muestra que haria, sin escribir
#     .\entrega_protocolo.ps1 -Forzar      # sobrescribe aunque haya cambios locales
#
# Los archivos viajan en base64 con su SHA-256, asi que se escriben byte por
# byte tal como se verificaron: UTF-8 sin BOM y finales LF.

[CmdletBinding()]
param(
    [switch]$Simular,
    [switch]$Forzar
)

$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest

# Sonda de codificacion. Este script va en UTF-8 con BOM; sin el BOM,
# PowerShell 5.1 lo lee como ANSI y la enie se parte en dos caracteres.
$sonda = 'ñ'
if ($sonda.Length -ne 1) {
    throw 'El instalador perdio su BOM y se leyo como ANSI. Vuelve a descargarlo sin abrirlo en un editor.'
}

# Los errores previstos se reportan limpios; throw queda para lo imprevisto.
function Stop-Entrega([string]$Mensaje) {
    Write-Host ''
    Write-Host $Mensaje -ForegroundColor Red
    exit 1
}

function Get-Sha256Hex([byte[]]$Bytes) {
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try {
        return (($sha.ComputeHash($Bytes) | ForEach-Object { $_.ToString('x2') }) -join '')
    }
    finally {
        $sha.Dispose()
    }
}

# Rutas absolutas siempre: [IO.File] resuelve las relativas contra el
# directorio del proceso, no contra la ubicacion actual de PowerShell.
$raiz = (Get-Location).ProviderPath
$pyproject = Join-Path $raiz 'pyproject.toml'
if (-not (Test-Path -LiteralPath $pyproject)) {
    Stop-Entrega "No encuentro pyproject.toml en $raiz. Ejecuta el instalador desde la raiz de NeuroDAC."
}
if (-not (Select-String -LiteralPath $pyproject -Pattern '^\s*name\s*=\s*"neurodac"' -Quiet)) {
    Stop-Entrega "El pyproject.toml de $raiz no es el de NeuroDAC."
}

