'@
    }
)

# Fase 1: decodificar y verificar TODO antes de escribir nada. Asi un
# instalador danado no deja una instalacion a medias.
$separador = [string][System.IO.Path]::DirectorySeparatorChar
$plan = foreach ($a in $archivos) {
    $bytes = [System.Convert]::FromBase64String(($a.Datos -replace '\s', ''))
    $hash = Get-Sha256Hex $bytes
    if ($hash -ne $a.Sha256) {
        Stop-Entrega "Integridad: $($a.Ruta) no coincide con su SHA-256. El instalador esta danado; vuelve a descargarlo. No se escribio nada."
    }
    $destino = Join-Path $raiz ($a.Ruta -replace '/', $separador)
    $estado = 'nuevo'
    if (Test-Path -LiteralPath $destino) {
        $actual = Get-Sha256Hex ([System.IO.File]::ReadAllBytes($destino))
        $estado = if ($actual -eq $hash) { 'sin cambios' } else { 'actualizado' }
    }
    [pscustomobject]@{ Ruta = $a.Ruta; Destino = $destino; Bytes = $bytes; Estado = $estado }
}

# Solo se protege lo que se va a sobrescribir: un archivo con cambios locales
# cuyo contenido ya es el de la entrega no corre riesgo.
if (Get-Command git -ErrorAction SilentlyContinue) {
    $porEscribir = @($plan | Where-Object { $_.Estado -ne 'sin cambios' } | ForEach-Object { $_.Ruta })
    if ($porEscribir.Count -gt 0) {
        $sucios = @(& git -C $raiz status --porcelain -- @porEscribir)
        if ($sucios.Count -gt 0 -and -not $Forzar) {
            Write-Host 'Estos archivos tienen cambios locales sin commitear que la entrega sobrescribiria:' -ForegroundColor Yellow
            $sucios | ForEach-Object { Write-Host "    $_" }
            Stop-Entrega 'Commitea o descarta esos cambios, o vuelve a correr con -Forzar. No se escribio nada.'
        }
    }
}

# Fase 2: escribir.
$escritos = 0
Write-Host ''
Write-Host 'Entrega: juegos: corregir el contrato con la página y separar audiencias' -ForegroundColor Cyan
foreach ($p in $plan) {
    if ($p.Estado -ne 'sin cambios') {
        if (-not $Simular) {
            $carpeta = Split-Path -Parent $p.Destino
            if (-not (Test-Path -LiteralPath $carpeta)) {
                New-Item -ItemType Directory -Force -Path $carpeta | Out-Null
            }
            [System.IO.File]::WriteAllBytes($p.Destino, $p.Bytes)
        }
        $escritos++
    }
    Write-Host ('  [{0,-11}] {1}' -f $p.Estado, $p.Ruta)
}

Write-Host ''
if ($Simular) {
    Write-Host "Simulacion: se escribirian $escritos archivo(s). No se toco nada." -ForegroundColor Yellow
}
else {
    Write-Host "Listo: $escritos archivo(s) escritos." -ForegroundColor Green
    Write-Host ''
    Write-Host 'Siguientes pasos:'
    Write-Host '  uv run pytest -q'
    Write-Host '  git add assets/games/engine.js assets/games/escenarios.js assets/quality.css content/divulgacion.es.json content/esquema.json docs/contrato-juegos.md docs/operacion.md interfaz.py pages/tiempo_real.py src/neurodac/content.py src/neurodac/game_page.py src/neurodac/ui.py tests/test_content.py tests/test_game_page.py tests/test_motor.py tests/test_ui.py tools/generar_manual.py tests/js/recibir.js'
    Write-Host '  git commit -m "juegos: corregir el contrato con la página y separar audiencias"'
}
